(function(){var c=document.getElementById('usre-home');if(!c)return;c.classList.add('usre-site');var st=document.createElement('style');st.textContent="\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');\n/* ===== USRE design system (shared by every website page) ===== */\n.usre-site{--nv:#0F2347;--nv2:#1a2f4e;--nv3:#0a1830;--ink:#101828;--tx:#344054;--mu:#5d6b82;--gd:#c9a84c;--gdk:#9a7724;--gdl:#f7f0dc;--bg:#f6f7f9;--br:#e6e9ef;--ok:#1f7a4d;\n  font-family:'Inter',Arial,sans-serif;color:var(--tx);background:#fff;font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;text-align:left}\n.usre-site *{box-sizing:border-box;margin:0;padding:0}\n.usre-site a{color:inherit;text-decoration:none}\n.usre-site img{max-width:100%;display:block}\n.usre-site .us-wrap{max-width:1180px;margin:0 auto;padding:0 24px}\n.usre-site .us-narrow{max-width:760px;margin:0 auto}\n/* type */\n.usre-site h1{font-size:54px;line-height:1.07;font-weight:800;letter-spacing:-1.4px;color:var(--ink)}\n.usre-site h2{font-size:38px;line-height:1.15;font-weight:800;letter-spacing:-.7px;color:var(--ink)}\n.usre-site h3{font-size:20px;line-height:1.3;font-weight:700;letter-spacing:-.2px;color:var(--ink)}\n.usre-site h1 em,.usre-site h2 em{font-style:normal;color:var(--gdk)}\n.usre-site .us-ey{display:inline-block;font-size:12.5px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:var(--gdk);margin-bottom:14px}\n.usre-site .us-lead{font-size:19.5px;line-height:1.6;color:var(--mu);max-width:620px}\n.usre-site .us-sub{font-size:18px;color:var(--mu);max-width:680px;margin:14px auto 0}\n.usre-site p+p{margin-top:16px}\n/* buttons */\n.usre-site .us-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;background:var(--gd);color:var(--nv);font-weight:700;font-size:16.5px;line-height:1;padding:18px 30px;border-radius:999px;border:0;cursor:pointer;transition:transform .15s,box-shadow .15s,background .15s;white-space:nowrap}\n.usre-site .us-btn:hover{transform:translateY(-1px);box-shadow:0 10px 24px rgba(201,168,76,.35)}\n.usre-site .us-btn svg{width:18px;height:18px}\n.usre-site .us-btn-sm{padding:12px 20px;font-size:14.5px}\n.usre-site .us-btn-ghost{background:transparent;color:var(--nv);box-shadow:inset 0 0 0 1.5px var(--nv)}\n.usre-site .us-btn-ghost:hover{background:var(--nv);color:#fff;box-shadow:none}\n.usre-site .us-link{font-weight:700;color:var(--nv);display:inline-flex;align-items:center;gap:6px}\n.usre-site .us-link svg{width:16px;height:16px;transition:transform .15s}\n.usre-site .us-link:hover svg{transform:translateX(3px)}\n/* header */\n.usre-site .us-hdr{position:sticky;top:0;z-index:60;background:var(--nv);border-bottom:2px solid var(--gd)}\n.usre-site .us-hdr-in{display:flex;align-items:center;gap:20px;height:76px}\n.usre-site .us-brand{display:flex;align-items:center;gap:12px;flex-shrink:0;margin-right:auto}\n.usre-site .us-brand img{width:46px;height:46px;border-radius:50%}\n.usre-site .us-wm{font-family:Georgia,'Times New Roman',serif;font-weight:700;font-size:19px;color:#fff;line-height:1.15;white-space:nowrap}\n.usre-site .us-wm em{font-style:normal;color:var(--gd)}\n.usre-site .us-wm small{display:block;font-style:italic;font-weight:400;font-size:11.5px;color:#aeb9cb;margin-top:3px}\n.usre-site .us-nav{display:flex;align-items:center;gap:2px}\n.usre-site .us-nav>a,.usre-site .us-dd>button{font:600 14.5px/1 'Inter',Arial,sans-serif;color:#d6dde8;padding:10px 11px;border-radius:8px;background:none;border:0;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:5px}\n.usre-site .us-nav>a:hover,.usre-site .us-dd>button:hover,.usre-site .us-nav>a.on{color:#fff;background:rgba(255,255,255,.07)}\n.usre-site .us-dd{position:relative}\n.usre-site .us-dd svg{width:14px;height:14px}\n.usre-site .us-dd-m{position:absolute;top:calc(100% + 8px);left:0;min-width:230px;background:#fff;border-radius:14px;box-shadow:0 20px 50px rgba(10,24,48,.25);padding:8px;display:none}\n.usre-site .us-dd.open .us-dd-m,.usre-site .us-dd:hover .us-dd-m{display:block}\n.usre-site .us-dd-m:before{content:'';position:absolute;left:0;right:0;top:-10px;height:10px}\n.usre-site .us-dd-m a{display:block;padding:11px 14px;border-radius:9px;color:var(--ink);font-weight:600;font-size:15px}\n.usre-site .us-dd-m a span{display:block;font-weight:400;font-size:13px;color:var(--mu);margin-top:2px}\n.usre-site .us-dd-m a:hover{background:var(--bg)}\n.usre-site .us-hdr .us-btn-sm{margin-left:8px}\n.usre-site .us-burger{display:none;background:none;border:0;color:#fff;cursor:pointer;padding:8px;margin-left:4px}\n.usre-site .us-burger svg{width:26px;height:26px;display:block}\n.usre-site .us-mnav{display:none;background:var(--nv);border-top:1px solid rgba(255,255,255,.1);padding:10px 24px 22px}\n.usre-site .us-mnav a{display:block;color:#e3e8f0;font-weight:600;font-size:16px;padding:12px 0;border-bottom:1px solid rgba(255,255,255,.08)}\n.usre-site .us-mnav .us-mg{font-size:11.5px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--gd);padding:16px 0 4px}\n.usre-site .us-mnav .us-msub{padding-left:14px}\n.usre-site .us-mnav a.us-btn{display:flex;margin-top:18px;border:0;color:var(--nv);padding:16px 24px}\n.usre-site .us-hdr.open .us-mnav{display:block}\n/* sections */\n.usre-site .us-main section,.usre-site .us-sec{padding:96px 0;scroll-margin-top:84px}\n.usre-site .us-alt{background:var(--bg)}\n.usre-site .us-head{text-align:center;max-width:760px;margin:0 auto 52px}\n.usre-site .us-head.left{text-align:left;margin-left:0}\n/* hero (light, used on every page) */\n.usre-site .us-hero{background:linear-gradient(180deg,#fbf9f3 0%,#fff 100%);padding:84px 0 88px;border-bottom:1px solid var(--br)}\n.usre-site .us-hero-g{display:grid;grid-template-columns:1.1fr .9fr;gap:64px;align-items:center}\n.usre-site .us-hero h1{margin-bottom:20px}\n.usre-site .us-hero .us-btn{margin-top:30px}\n.usre-site .us-trust{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:22px;font-size:14px;color:var(--mu)}\n.usre-site .us-trust span{display:inline-flex;align-items:center;gap:7px}\n.usre-site .us-trust svg{width:16px;height:16px;color:var(--gdk)}\n.usre-site .us-phero{background:linear-gradient(180deg,#fbf9f3 0%,#fff 100%);padding:80px 0 72px;border-bottom:1px solid var(--br)}\n.usre-site .us-phero h1{font-size:48px;max-width:860px;margin-bottom:20px}\n.usre-site .us-phero .us-lead{max-width:780px}\n/* report card visual */\n.usre-site .us-report{background:#fff;border:1px solid var(--br);border-radius:22px;box-shadow:0 30px 70px rgba(15,35,71,.14);overflow:hidden;max-width:460px;margin-left:auto}\n.usre-site .us-report .rh{background:var(--nv);color:#fff;padding:24px 26px;text-align:center}\n.usre-site .us-report .rl{font-size:11.5px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:var(--gd)}\n.usre-site .us-report .rs{font-size:54px;font-weight:800;letter-spacing:-1.5px;line-height:1.05;margin-top:6px}\n.usre-site .us-report .rs span{font-size:20px;font-weight:600;color:#9fb0c8}\n.usre-site .us-report .rv{display:inline-block;margin-top:8px;font-size:12.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#fff;background:#b42318;padding:5px 12px;border-radius:999px}\n.usre-site .us-report .rb{padding:8px 26px 6px}\n.usre-site .us-report .row{display:flex;justify-content:space-between;gap:16px;padding:14px 0;border-bottom:1px solid var(--br);font-size:15px}\n.usre-site .us-report .row:last-child{border-bottom:0}\n.usre-site .us-report .row b{color:var(--ink);white-space:nowrap}\n.usre-site .us-report .tag{font-size:12px;color:var(--mu);text-align:center;padding:0 0 18px}\n/* stats bar */\n.usre-site .us-stats{background:var(--nv);padding:34px 0}\n.usre-site .us-stats .us-wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;text-align:center}\n.usre-site .us-stats b{display:block;font-size:34px;font-weight:800;color:#fff;letter-spacing:-.5px;line-height:1.15}\n.usre-site .us-stats span{font-size:14px;color:#aeb9cb}\n.usre-site .us-stats .us-wrap>div+div{border-left:1px solid rgba(255,255,255,.1)}\n/* cards & icons */\n.usre-site .us-g3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}\n.usre-site .us-g2{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}\n.usre-site .us-card{background:#fff;border:1px solid var(--br);border-radius:18px;padding:32px;box-shadow:0 1px 2px rgba(16,24,40,.04)}\n.usre-site a.us-card{display:block;transition:box-shadow .2s,transform .2s,border-color .2s}\n.usre-site a.us-card:hover{transform:translateY(-3px);box-shadow:0 18px 40px rgba(15,35,71,.10);border-color:#d8dde6}\n.usre-site .us-card h3{margin-bottom:10px}\n.usre-site .us-card p{font-size:16px;color:var(--mu)}\n.usre-site .us-card .us-link{margin-top:20px}\n.usre-site .us-ic{width:52px;height:52px;border-radius:14px;background:var(--gdl);color:var(--gdk);display:flex;align-items:center;justify-content:center;margin-bottom:22px}\n.usre-site .us-ic svg{width:26px;height:26px}\n/* steps */\n.usre-site .us-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;counter-reset:s}\n.usre-site .us-step{position:relative;padding:32px;border-radius:18px;background:#fff;border:1px solid var(--br)}\n.usre-site .us-step .n{width:40px;height:40px;border-radius:50%;background:var(--nv);color:var(--gd);font-weight:800;display:flex;align-items:center;justify-content:center;margin-bottom:20px}\n.usre-site .us-step h3{margin-bottom:8px}\n.usre-site .us-step p{font-size:16px;color:var(--mu)}\n/* text block */\n.usre-site .us-prose p{font-size:18px;color:var(--tx)}\n.usre-site .us-split{display:grid;grid-template-columns:.9fr 1.1fr;gap:64px;align-items:start}\n.usre-site .us-quote{font-family:Georgia,'Times New Roman',serif;font-size:28px;line-height:1.4;color:var(--nv);border-left:4px solid var(--gd);padding-left:24px;margin-top:28px}\n/* option / path cards */\n.usre-site .us-paths{display:grid;gap:28px}\n.usre-site .us-path{background:#fff;border:1px solid var(--br);border-radius:22px;padding:40px;display:grid;grid-template-columns:1.05fr .95fr;gap:44px;box-shadow:0 1px 2px rgba(16,24,40,.04)}\n.usre-site .us-tag{display:inline-block;font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:var(--nv);background:var(--gdl);border-radius:999px;padding:7px 13px;margin-bottom:16px}\n.usre-site .us-path h3{font-size:26px;margin-bottom:6px}\n.usre-site .us-tl{font-size:17px;font-weight:600;color:var(--gdk);margin-bottom:14px}\n.usre-site .us-path p{font-size:16.5px;color:var(--mu)}\n.usre-site .us-lbl{font-size:12px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:var(--mu);margin-bottom:12px}\n.usre-site .us-check{list-style:none}\n.usre-site .us-check li{position:relative;padding-left:32px;font-size:16px;color:var(--tx);margin-bottom:12px}\n.usre-site .us-check li:before{content:'';position:absolute;left:0;top:3px;width:20px;height:20px;border-radius:50%;background:var(--gdl)}\n.usre-site .us-check li:after{content:'';position:absolute;left:6px;top:8px;width:8px;height:5px;border-left:2px solid var(--gdk);border-bottom:2px solid var(--gdk);transform:rotate(-45deg)}\n.usre-site .us-check li b{color:var(--ink)}\n.usre-site .us-callout{margin-top:22px;background:var(--bg);border-left:3px solid var(--gd);border-radius:0 12px 12px 0;padding:16px 18px}\n.usre-site .us-callout b{display:block;color:var(--ink);font-size:15.5px;margin-bottom:4px}\n.usre-site .us-callout span{font-size:14.5px;color:var(--mu)}\n.usre-site .us-big{display:flex;align-items:center;gap:18px;background:var(--nv);color:#fff;border-radius:16px;padding:20px 22px;margin-top:22px}\n.usre-site .us-big b{font-size:44px;font-weight:800;color:var(--gd);line-height:1;letter-spacing:-1px}\n.usre-site .us-big strong{display:block;font-size:15px}\n.usre-site .us-big span{font-size:14px;color:#aeb9cb}\n/* table */\n.usre-site .us-tw{overflow-x:auto;border:1px solid var(--br);border-radius:18px;background:#fff}\n.usre-site .us-table{width:100%;border-collapse:collapse;min-width:640px;font-size:15.5px}\n.usre-site .us-table th,.usre-site .us-table td{padding:18px 22px;text-align:left;border-bottom:1px solid var(--br);vertical-align:top}\n.usre-site .us-table thead th{background:var(--nv);color:#fff;font-weight:700;font-size:14.5px}\n.usre-site .us-table tbody th{color:var(--ink);font-weight:700;width:22%;background:var(--bg)}\n.usre-site .us-table tr:last-child th,.usre-site .us-table tr:last-child td{border-bottom:0}\n/* chips (carriers) */\n.usre-site .us-chips{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}\n.usre-site .us-chips div{background:#fff;border:1px solid var(--br);border-radius:14px;padding:22px 16px;text-align:center;font-weight:700;color:var(--nv);font-size:16px}\n.usre-site .us-note{font-size:14px;color:var(--mu);margin-top:28px;line-height:1.6}\n/* faq */\n.usre-site .us-faq{max-width:820px;margin:0 auto}\n.usre-site .us-faq details{border-bottom:1px solid var(--br)}\n.usre-site .us-faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px 0;font-size:18px;font-weight:700;color:var(--ink)}\n.usre-site .us-faq summary::-webkit-details-marker{display:none}\n.usre-site .us-faq summary .pm{flex-shrink:0;width:30px;height:30px;border-radius:50%;background:var(--bg);display:flex;align-items:center;justify-content:center;transition:transform .2s}\n.usre-site .us-faq summary .pm svg{width:16px;height:16px;color:var(--nv)}\n.usre-site .us-faq details[open] summary .pm{transform:rotate(45deg);background:var(--gdl)}\n.usre-site .us-faq details p{padding:0 50px 24px 0;color:var(--mu);font-size:16.5px}\n/* cta band */\n.usre-site .us-cta{background:var(--nv);color:#fff;text-align:center;padding:92px 0}\n.usre-site .us-cta h2{color:#fff;max-width:760px;margin:0 auto 14px}\n.usre-site .us-cta p{color:#c3ccda;font-size:18.5px;max-width:640px;margin:0 auto 32px}\n.usre-site .us-cta .us-alt-l{display:block;margin-top:20px;font-size:15px;color:#c3ccda}\n.usre-site .us-cta .us-alt-l a{color:#fff;font-weight:700;border-bottom:1px solid var(--gd);padding-bottom:1px}\n.usre-site .us-cta .us-trust{justify-content:center;color:#aeb9cb}\n.usre-site .us-cta .us-trust svg{color:var(--gd)}\n/* legal */\n.usre-site .us-legal h2{font-size:24px;margin:48px 0 8px;padding-top:28px;border-top:1px solid var(--br)}\n.usre-site .us-legal h2:first-child{margin-top:0;padding-top:0;border-top:0}\n.usre-site .us-legal h3{font-size:17px;margin:28px 0 8px}\n.usre-site .us-legal p{font-size:16px;color:var(--tx)}\n.usre-site .us-legal p+p{margin-top:12px}\n.usre-site .us-legal .upd{font-size:14px;color:var(--mu)}\n.usre-site .us-legal .note{margin-top:36px;background:var(--bg);border-radius:12px;padding:18px 20px;font-size:14px;color:var(--mu)}\n/* footer */\n.usre-site .us-ftr{background:var(--nv3);color:#aeb9cb;font-size:14.5px;padding:72px 0 36px}\n.usre-site .us-ftr-g{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:40px}\n.usre-site .us-ftr .us-brand{margin-bottom:16px}\n.usre-site .us-ftr-g a.us-brand{display:flex;color:#fff}\n.usre-site .us-ftr p{max-width:340px;line-height:1.6}\n.usre-site .us-ftr h4{font-size:12px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--gd);margin-bottom:16px}\n.usre-site .us-ftr-g a{display:block;color:#d6dde8;margin-bottom:10px}\n.usre-site .us-ftr-g a:hover{color:#fff}\n.usre-site .us-ftr-legal{margin-top:52px;padding-top:28px;border-top:1px solid rgba(255,255,255,.1);font-size:12.5px;line-height:1.7;color:#8d9ab0}\n.usre-site .us-ftr-legal p{max-width:none}\n.usre-site .us-ftr-legal a{color:#d6dde8;text-decoration:underline}\n.usre-site .us-ftr-c{margin-top:16px}\n/* responsive */\n@media(max-width:1120px){\n  .usre-site .us-nav,.usre-site .us-hdr-in>.us-btn-sm{display:none}\n  .usre-site .us-burger{display:block}\n}\n@media(max-width:900px){\n  .usre-site h1,.usre-site .us-phero h1{font-size:40px;letter-spacing:-.9px}\n  .usre-site h2{font-size:30px}\n  .usre-site .us-main section,.usre-site .us-sec{padding:68px 0}\n  .usre-site .us-hero{padding:56px 0 64px}\n  .usre-site .us-phero{padding:56px 0 52px}\n  .usre-site .us-hero-g,.usre-site .us-split,.usre-site .us-path{grid-template-columns:1fr;gap:36px}\n  .usre-site .us-report{margin:0 auto}\n  .usre-site .us-g3,.usre-site .us-steps,.usre-site .us-g2{grid-template-columns:1fr}\n  .usre-site .us-stats .us-wrap{grid-template-columns:repeat(2,1fr);row-gap:26px}\n  .usre-site .us-stats .us-wrap>div+div{border-left:0}\n  .usre-site .us-chips{grid-template-columns:repeat(2,1fr)}\n  .usre-site .us-ftr-g{grid-template-columns:1fr 1fr}\n  .usre-site .us-ftr-g>div:first-child{grid-column:1/-1}\n  .usre-site .us-head{margin-bottom:36px}\n}\n@media(max-width:600px){\n  .usre-site{font-size:16px}\n  .usre-site .us-wrap{padding:0 20px}\n  .usre-site h1,.usre-site .us-phero h1{font-size:34px}\n  .usre-site h2{font-size:27px}\n  .usre-site .us-lead{font-size:17.5px}\n  .usre-site .us-hdr-in{height:66px}\n  .usre-site .us-wm{font-size:16.5px}\n  .usre-site .us-wm small{display:none}\n  .usre-site .us-brand img{width:40px;height:40px}\n  .usre-site .us-btn{width:100%;white-space:normal;text-align:center}\n  .usre-site .us-card,.usre-site .us-step{padding:24px}\n  .usre-site .us-ic{width:44px;height:44px;margin-bottom:16px}\n  .usre-site .us-ic svg{width:22px;height:22px}\n  .usre-site .us-step .n{margin-bottom:14px}\n  .usre-site .us-path{padding:28px 22px}\n  .usre-site .us-stats b{font-size:28px}\n  .usre-site .us-quote{font-size:23px}\n  .usre-site .us-faq summary{font-size:17px}\n  .usre-site .us-faq details p{padding-right:0}\n  .usre-site .us-ftr-g{grid-template-columns:1fr}\n}\n\n/* home: badge strip */\n.usre-site .us-badges{padding:44px 0 40px;border-bottom:1px solid var(--br);text-align:center;overflow:hidden}\n.usre-site .us-badges h2{font-size:24px;letter-spacing:-.3px;margin-bottom:26px;padding:0 20px}\n.usre-site .us-bvp{position:relative;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 7%,#000 93%,transparent);mask-image:linear-gradient(90deg,transparent,#000 7%,#000 93%,transparent)}\n.usre-site .us-btrack{display:flex;width:max-content;animation:usSlide 48s linear infinite}\n.usre-site .us-bvp:hover .us-btrack{animation-play-state:paused}\n@keyframes usSlide{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n.usre-site .us-bset{display:flex}\n.usre-site .us-b{flex:0 0 auto;width:156px;display:flex;flex-direction:column;align-items:center;gap:10px;padding:4px 0}\n.usre-site .us-b svg{width:96px;height:96px;filter:drop-shadow(0 6px 12px rgba(15,35,71,.16))}\n.usre-site .us-b span{font-size:13px;font-weight:600;line-height:1.3;color:var(--tx);max-width:134px}\n@media(max-width:600px){.usre-site .us-badges h2{font-size:20px}.usre-site .us-b{width:122px}.usre-site .us-b svg{width:78px;height:78px}.usre-site .us-b span{font-size:12px;max-width:110px}.usre-site .us-btrack{animation-duration:38s}}\n@media(prefers-reduced-motion:reduce){.usre-site .us-btrack{animation:none;width:100%;justify-content:center}.usre-site .us-bset+.us-bset{display:none}.usre-site .us-bset{flex-wrap:wrap;justify-content:center}}\n";document.head.appendChild(st);c.innerHTML="<header class=\"us-hdr\">\n  <div class=\"us-wrap us-hdr-in\">\n    <a class=\"us-brand\" data-href=\"home\"><img data-src=\"logo\" alt=\"US Retirement Educators\"><span class=\"us-wm\">US <em>Retirement</em> Educators<small>A better retirement starts with a better education.</small></span></a>\n    <nav class=\"us-nav\" aria-label=\"Primary\">\n      <a data-href=\"home#approach\">Our Approach</a>\n      <div class=\"us-dd\"><button type=\"button\" aria-expanded=\"false\">Solutions <i data-ic=\"chev\"></i></button>\n        <div class=\"us-dd-m\">\n          <a href=\"/growth\">Growth<span>Protected growth for your savings</span></a>\n          <a href=\"/income\">Income<span>A paycheck you can't outlive</span></a>\n          <a href=\"/roth-conversion\">Roth Conversion<span>Get ahead of RMDs and taxes</span></a>\n        </div>\n      </div>\n      <a data-href=\"home#about\">About Us</a>\n      <a data-href=\"home#faq\">FAQ</a>\n      <a data-href=\"team\">Meet the Team</a>\n      <a href=\"/carriers\">Carrier Partners</a>\n    </nav>\n    <a class=\"us-btn us-btn-sm\" data-href=\"assess\">Take the Assessment</a>\n    <button class=\"us-burger\" type=\"button\" aria-label=\"Menu\"><i data-ic=\"menu\"></i></button>\n  </div>\n  <div class=\"us-mnav\">\n    <a data-href=\"home#approach\">Our Approach</a>\n    <div class=\"us-mg\">Solutions</div>\n    <a class=\"us-msub\" href=\"/growth\">Growth</a>\n    <a class=\"us-msub\" href=\"/income\">Income</a>\n    <a class=\"us-msub\" href=\"/roth-conversion\">Roth Conversion</a>\n    <a data-href=\"home#about\">About Us</a>\n    <a data-href=\"home#faq\">FAQ</a>\n    <a data-href=\"team\">Meet the Team</a>\n    <a href=\"/carriers\">Carrier Partners</a>\n    <a class=\"us-btn\" data-href=\"assess\">Take the Assessment</a>\n  </div>\n</header>\n<main class=\"us-main\">\n\n\n<div class=\"us-hero\"><div class=\"us-wrap us-hero-g\">\n  <div>\n    <span class=\"us-ey\">Retirement Risk Education</span>\n    <h1>Your retirement shouldn&rsquo;t depend on <em>the next market cycle.</em></h1>\n    <p class=\"us-lead\">We help families protect the retirement they&rsquo;ve spent decades building, with strategies designed to guard against market downturns, not just chase growth.</p>\n    <a class=\"us-btn\" data-href=\"assess\">Take the Free 4-Minute Risk Assessment <i data-ic=\"arrow\"></i></a>\n    <div class=\"us-trust\"><span><i data-ic=\"check\"></i>100% free</span><span><i data-ic=\"clock\"></i>4 minutes</span><span><i data-ic=\"lock\"></i>Confidential</span><span><i data-ic=\"bolt\"></i>Instant results</span></div>\n  </div>\n  <div class=\"us-report\" aria-label=\"Sample retirement risk report\">\n    <div class=\"rh\"><div class=\"rl\">Retirement Risk Analysis</div><div class=\"rs\">164<span>/248</span></div><div class=\"rv\">High Risk</div></div>\n    <div class=\"rb\">\n      <div class=\"row\"><span>At risk in a 30% market drop</span><b>&minus;$146,000</b></div>\n      <div class=\"row\"><span>Amount to move into a safe product</span><b>$203,000</b></div>\n      <div class=\"row\"><span>Monthly income gap</span><b>$3,000 / mo</b></div>\n      <div class=\"row\"><span>Long-term care exposure</span><b>$156K&ndash;$473K</b></div>\n    </div>\n    <div class=\"tag\">Sample report for illustration only</div>\n  </div>\n</div></div>\n\n<div class=\"us-stats\"><div class=\"us-wrap\">\n  <div><b>6,000+</b><span>Families helped nationwide</span></div>\n  <div><b>50</b><span>States, licensed everywhere</span></div>\n  <div><b>100+</b><span>Years of combined experience</span></div>\n  <div><b>5&#9733;</b><span>Rated by our clients</span></div>\n</div></div>\n\n<div class=\"us-badges\" id=\"us-badges\"><span class=\"us-ey\">Licensed &middot; Certified &middot; Experienced</span><h2>How we help families protect their retirement</h2><div class=\"us-bvp\"><div class=\"us-btrack\"></div></div></div>\n\n<section id=\"approach\"><div class=\"us-wrap\">\n  <div class=\"us-head\"><span class=\"us-ey\">The Problem We Solve</span><h2>The retirement risk most people don&rsquo;t see coming</h2><p class=\"us-sub\">During your working years, a market downturn is a setback. In retirement, the same downturn can be permanent, because you&rsquo;re no longer adding money in. You&rsquo;re taking it out.</p></div>\n  <div class=\"us-g3\">\n    <div class=\"us-card\"><div class=\"us-ic\"><i data-ic=\"down\"></i></div><h3>Market timing risk</h3><p>A downturn right before or during retirement can permanently reduce the income your savings are able to provide, even if the market eventually recovers.</p></div>\n    <div class=\"us-card\"><div class=\"us-ic\"><i data-ic=\"hourglass\"></i></div><h3>No time to wait it out</h3><p>Unlike your working years, retirement often doesn&rsquo;t give you the runway to simply wait for a recovery while still covering your bills.</p></div>\n    <div class=\"us-card\"><div class=\"us-ic\"><i data-ic=\"calc\"></i></div><h3>The withdrawal trap</h3><p>Taking income out of a portfolio during a down market, known as sequence-of-returns risk, can compound losses far faster than most people expect.</p></div>\n  </div>\n</div></section>\n\n<section class=\"us-alt\"><div class=\"us-wrap\">\n  <div class=\"us-head\"><span class=\"us-ey\">How It Works</span><h2>Three steps to a clearer picture</h2><p class=\"us-sub\">No pressure, no obligation. Just a clear, honest look at where you stand today.</p></div>\n  <div class=\"us-steps\">\n    <div class=\"us-step\"><div class=\"n\">1</div><h3>Take the assessment</h3><p>Answer a few quick questions about your retirement plan and market exposure. It takes about 4 minutes.</p></div>\n    <div class=\"us-step\"><div class=\"n\">2</div><h3>Get your risk score</h3><p>Receive a personalized report showing exactly where your plan may be exposed to market risk.</p></div>\n    <div class=\"us-step\"><div class=\"n\">3</div><h3>Talk to a specialist</h3><p>Book a free, no-pressure call with a licensed retirement specialist to walk through your results.</p></div>\n  </div>\n  <div style=\"text-align:center;margin-top:44px\"><a class=\"us-btn\" data-href=\"assess\">Start My Free Assessment <i data-ic=\"arrow\"></i></a></div>\n</div></section>\n\n<section><div class=\"us-wrap\">\n  <div class=\"us-head\"><span class=\"us-ey\">Once You Know Your Number</span><h2>Explore your options</h2><p class=\"us-sub\">Your assessment shows you where the risk is. These walk you through the actual strategies people use to address it.</p></div>\n  <div class=\"us-g3\">\n    <a class=\"us-card\" href=\"/growth\"><div class=\"us-ic\"><i data-ic=\"up\"></i></div><h3>Growth</h3><p>Strong growth without risking your principal or your profit, no matter what the market does.</p><span class=\"us-link\">Explore Growth <i data-ic=\"arrow\"></i></span></a>\n    <a class=\"us-card\" href=\"/income\"><div class=\"us-ic\"><i data-ic=\"wallet\"></i></div><h3>Income</h3><p>Turning part of your savings into income you can&rsquo;t outlive, regardless of the market.</p><span class=\"us-link\">Explore Income <i data-ic=\"arrow\"></i></span></a>\n    <a class=\"us-card\" href=\"/roth-conversion\"><div class=\"us-ic\"><i data-ic=\"receipt\"></i></div><h3>Roth Conversion</h3><p>Getting ahead of RMDs and IRMAA by converting on your terms, not the IRS&rsquo;s schedule.</p><span class=\"us-link\">Explore Roth Conversion <i data-ic=\"arrow\"></i></span></a>\n  </div>\n</div></section>\n\n<section class=\"us-alt\" id=\"about\"><div class=\"us-wrap us-split\">\n  <div><span class=\"us-ey\">Who We Are</span><h2>Educators first. That&rsquo;s the whole model.</h2><p class=\"us-quote\">&ldquo;A better retirement starts with a better education.&rdquo;</p></div>\n  <div class=\"us-prose\">\n    <p>US Retirement Educators is a team of licensed retirement specialists serving clients across all 50 states, focused on helping people better understand and reduce the risks that can impact their retirement.</p>\n    <p>Our philosophy is simple: education comes before recommendation. We believe better retirement decisions start with understanding the risks you face, the options available to you, and the tradeoffs behind each one.</p>\n    <p>We&rsquo;ve partnered with leading retirement professionals and independent insurance organizations across the country to bring together experienced minds, proven strategies, and modern technology, all with one goal: helping retirees make more informed decisions about protecting what they&rsquo;ve worked a lifetime to build.</p>\n    <p style=\"margin-top:26px\"><a class=\"us-link\" data-href=\"team\">Meet the team <i data-ic=\"arrow\"></i></a></p>\n  </div>\n</div></section>\n\n<section id=\"faq\"><div class=\"us-wrap\">\n  <div class=\"us-head\"><span class=\"us-ey\">Common Questions</span><h2>Frequently asked questions</h2></div>\n  <div class=\"us-faq\">\n    <details><summary>What is the Retirement Risk Assessment?<span class=\"pm\"><i data-ic=\"plus\"></i></span></summary><p>It&rsquo;s a free, confidential diagnostic, about 4 minutes, that scores your retirement plan against the biggest risks retirees face from a market downturn. At the end, you get a personalized risk score and a report showing your specific vulnerabilities.</p></details>\n    <details><summary>Is it actually free?<span class=\"pm\"><i data-ic=\"plus\"></i></span></summary><p>Yes. 100% free, with no obligation. There&rsquo;s no cost to take the assessment or to talk through your results with a specialist afterward.</p></details>\n    <details><summary>Am I going to get a hard sales pitch?<span class=\"pm\"><i data-ic=\"plus\"></i></span></summary><p>No. The call that follows is meant to walk you through your specific results, not to push a product. If something is recommended, it&rsquo;s tied directly to a gap your own answers surfaced.</p></details>\n    <details><summary>Is my information kept confidential?<span class=\"pm\"><i data-ic=\"plus\"></i></span></summary><p>Yes. Your answers and information are confidential and are never sold or shared.</p></details>\n    <details><summary>Who&rsquo;s actually behind US Retirement Educators?<span class=\"pm\"><i data-ic=\"plus\"></i></span></summary><p>A team of licensed retirement specialists serving clients in all 50 states, partnered with leading retirement professionals and independent insurance organizations to bring together experience, proven strategies, and modern technology behind every assessment.</p></details>\n  </div>\n</div></section>\n\n<div class=\"us-cta\"><div class=\"us-wrap\">\n  <h2>See where you stand before the next downturn hits</h2>\n  <p>Take our free 4-minute diagnostic and get a personalized retirement risk score. No cost, no obligation, just clarity.</p>\n  <a class=\"us-btn\" data-href=\"assess\">Start My Risk Assessment <i data-ic=\"arrow\"></i></a>\n  <div class=\"us-trust\"><span><i data-ic=\"lock\"></i>Confidential</span><span><i data-ic=\"chat\"></i>No sales pressure</span><span><i data-ic=\"shield\"></i>Licensed specialists</span></div>\n</div></div></main>\n<footer class=\"us-ftr\">\n  <div class=\"us-wrap\">\n    <div class=\"us-ftr-g\">\n      <div>\n        <a class=\"us-brand\" data-href=\"home\"><img data-src=\"logo\" alt=\"\"><span class=\"us-wm\">US <em>Retirement</em> Educators</span></a>\n        <p>Helping families understand and reduce market risk in retirement, licensed in all 50 states.</p>\n      </div>\n      <div><h4>Solutions</h4><a href=\"/growth\">Growth</a><a href=\"/income\">Income</a><a href=\"/roth-conversion\">Roth Conversion</a></div>\n      <div><h4>Company</h4><a data-href=\"home#approach\">Our Approach</a><a data-href=\"home#about\">About Us</a><a data-href=\"team\">Meet the Team</a><a href=\"/carriers\">Carrier Partners</a><a data-href=\"home#faq\">FAQ</a></div>\n      <div><h4>Get Started</h4><a data-href=\"assess\">Take the Assessment</a><a data-href=\"book\">Book a Call</a><a href=\"/disclosures\">Disclosures &amp; Privacy</a></div>\n    </div>\n    <div class=\"us-ftr-legal\">\n      <p>US Retirement Educators is not affiliated with the U.S. government or any government agency. Content on this website is for educational purposes only and does not constitute financial, investment, insurance, or tax advice. Any guarantees referenced are backed solely by the financial strength and claims-paying ability of the issuing insurance company. Please consult a licensed professional before making financial decisions. See our full <a href=\"/disclosures\">Disclosures, Privacy Policy &amp; SMS Terms</a> for details.</p>\n      <p class=\"us-ftr-c\">&copy; <span data-year></span> US Retirement Educators. All rights reserved.</p>\n    </div>\n  </div>\n</footer>";})();

